#!/usr/bin/env python3
"""
handle_card_feedback.py — Process Telegram RATE/IMAGE feedback for news cards.

Usage:
    python3 handle_card_feedback.py --payload "oc_r:20260522-101746:8" --chat-id "..." --user-id "..."

Always exits 0 (fail-open). Prints RATE_RECORDED, RATE_INVALID, ARTICLE_NOT_FOUND, or RATE_MENU_SENT.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import urllib.parse
import urllib.request

_SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
if _SCRIPT_DIR not in sys.path:
    sys.path.insert(0, _SCRIPT_DIR)

from editorial_db import (
    Article,
    DEFAULT_DB_PATH,
    lookup_by_alert_id,
    lookup_by_message_id,
    lookup_by_run_id,
    record_rating,
)

OPENCLAW_JSON = os.path.expanduser("~/.openclaw/openclaw.json")

_RE_ARTICLE_RATE = re.compile(r"^oc_r:(.+):(\d{1,2})$")
_RE_IMAGE_RATE = re.compile(r"^oc_ri:(.+):(\d{1,2})$")
_RE_IMAGE_MENU = re.compile(r"^oc_ri_menu:(.+)$")
_RE_TEXT_RATE = re.compile(r"^(?:RATE|rate)\s+(\d{1,2})\b")
_RE_TEXT_IMAGE = re.compile(r"^(?:IMAGE|image)\s+(\d{1,2})\b")
_RE_ALERT = re.compile(r"\bta-([A-Za-z0-9_-]+)\b")


def load_bot_token() -> str:
    try:
        with open(OPENCLAW_JSON, encoding="utf-8") as f:
            data = json.load(f)
        return (data.get("channels") or {}).get("telegram", {}).get("botToken", "")
    except (OSError, json.JSONDecodeError):
        return ""


def telegram_request(token: str, method: str, data: dict | None = None) -> dict:
    url = f"https://api.telegram.org/bot{token}/{method}"
    encoded = urllib.parse.urlencode(data or {}).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=encoded,
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=60) as resp:
        raw = resp.read().decode("utf-8")
    result = json.loads(raw)
    if not result.get("ok"):
        desc = result.get("description", "unknown Telegram error")
        raise RuntimeError(desc)
    return result


def send_message(
    token: str,
    chat_id: str,
    text: str,
    *,
    reply_to_message_id: int | None = None,
    reply_markup: dict | None = None,
) -> None:
    payload: dict[str, str] = {
        "chat_id": chat_id,
        "text": text,
        "parse_mode": "HTML",
    }
    if reply_to_message_id is not None:
        payload["reply_to_message_id"] = str(reply_to_message_id)
    if reply_markup:
        payload["reply_markup"] = json.dumps(reply_markup)
    telegram_request(token, "sendMessage", payload)


def build_image_score_keyboard(run_id: str) -> dict:
    rows: list[list[dict[str, str]]] = []
    rows.append(
        [{"text": str(n), "callback_data": f"oc_ri:{run_id}:{n}"} for n in range(1, 6)]
    )
    rows.append(
        [{"text": str(n), "callback_data": f"oc_ri:{run_id}:{n}"} for n in range(6, 11)]
    )
    return {"inline_keyboard": rows}


def parse_score(value: str) -> int | None:
    try:
        score = int(value)
    except ValueError:
        return None
    if 1 <= score <= 10:
        return score
    return None


def resolve_article(
    *,
    chat_id: str | None,
    reply_to_message_id: str | None,
    run_id: str | None,
    alert_id: str | None,
    db_path: str,
) -> Article | None:
    if run_id:
        article = lookup_by_run_id(run_id, db_path)
        if article:
            return article
    if alert_id:
        article = lookup_by_alert_id(alert_id, db_path)
        if article:
            return article
    if chat_id and reply_to_message_id:
        try:
            msg_id = int(reply_to_message_id)
        except ValueError:
            return None
        return lookup_by_message_id(chat_id, msg_id, db_path)
    return None


def extract_alert_from_text(text: str) -> str | None:
    match = _RE_ALERT.search(text)
    return match.group(1) if match else None


def parse_input(
    payload: str | None, message_text: str | None
) -> tuple[str, str | None, int | None, str | None] | None:
    """Returns (action, run_id, score, alert_run_id). action: rate_article|rate_image|image_menu|None"""
    if payload:
        payload = payload.strip()
        menu = _RE_IMAGE_MENU.match(payload)
        if menu:
            return ("image_menu", menu.group(1).strip(), None, None)
        art = _RE_ARTICLE_RATE.match(payload)
        if art:
            score = parse_score(art.group(2))
            if score is None:
                return None
            return ("rate_article", art.group(1).strip(), score, None)
        img = _RE_IMAGE_RATE.match(payload)
        if img:
            score = parse_score(img.group(2))
            if score is None:
                return None
            return ("rate_image", img.group(1).strip(), score, None)

    if message_text:
        text = message_text.strip()
        img_match = _RE_TEXT_IMAGE.match(text)
        if img_match:
            score = parse_score(img_match.group(1))
            if score is None:
                return None
            alert_run = extract_alert_from_text(text)
            return ("rate_image", None, score, alert_run)
        rate_match = _RE_TEXT_RATE.match(text)
        if rate_match:
            score = parse_score(rate_match.group(1))
            if score is None:
                return None
            alert_run = extract_alert_from_text(text)
            return ("rate_article", None, score, alert_run)

    return None


def record_and_confirm(
    *,
    article: Article,
    event_type: str,
    score: int,
    user_id: str | None,
    username: str | None,
    source: str,
    raw_payload: str | None,
    db_path: str,
    token: str,
    chat_id: str,
    reply_to_message_id: int | None,
) -> str:
    record_rating(
        article.id,
        event_type,
        score,
        user_id=user_id,
        user_username=username,
        source=source,
        raw_payload=raw_payload,
        db_path=db_path,
    )
    label = "article" if event_type == "rate_article" else "image"
    msg = (
        f"Rated {label} <b>{score}/10</b> for ALERT: <code>{article.alert_id}</code>"
    )
    if token and chat_id:
        send_message(
            token,
            chat_id,
            msg,
            reply_to_message_id=reply_to_message_id,
        )
    kind = "article" if event_type == "rate_article" else "image"
    return f"RATE_RECORDED: {article.alert_id} {kind}={score}"


